    @ParameterizedTest @ValueSource(strings = { "foreign", "partial", "directory", "symlink" })
    void unknownFinalIdentityIsPreservedWithoutAPropertyFallback(String kind,
            @TempDir(cleanup = CleanupMode.NEVER) Path temporary) throws Exception {
        LmdbCompatibilityFixtures.extract("canonical-iri-format-2.zip", temporary);
        Path directory = temporary.resolve("store"), target = directory.resolve(IDENTITY);
        byte[] policy = Files.readAllBytes(directory.resolve("store.properties"));
        byte[] unknown = kind.equals("partial") ? HEADER.getBytes(StandardCharsets.US_ASCII)
                : "foreign-owner-data\n".getBytes(StandardCharsets.US_ASCII);
        Path foreign = temporary.resolve("foreign-owner");
        if (kind.equals("directory")) { Files.createDirectory(target); Files.write(target.resolve("keep"), unknown); }
        else if (kind.equals("symlink")) { Files.write(foreign, unknown); Files.createSymbolicLink(target, foreign); }
        else { Files.write(target, unknown); }
        CapturingStore store = new CapturingStore(directory, config(false));
        SailRepository repository = open(store);
        try {
            CanonicalIriCompatibilityProcess.verify(repository,
                    CanonicalIriCompatibilityProcess.load(temporary.resolve("manifest.properties")));
            assertNull(store.properties.savedStoreId(), "refused auxiliary identity must not mutate legacy policy");
        } finally { repository.shutDown(); }
        assertArrayEquals(policy, Files.readAllBytes(directory.resolve("store.properties")));
        if (kind.equals("directory")) {
            assertTrue(Files.isDirectory(target, LinkOption.NOFOLLOW_LINKS));
            assertArrayEquals(unknown, Files.readAllBytes(target.resolve("keep")));
        } else if (kind.equals("symlink")) {
            assertTrue(Files.isSymbolicLink(target)); assertEquals(foreign, Files.readSymbolicLink(target));
            assertArrayEquals(unknown, Files.readAllBytes(foreign));
        } else { assertArrayEquals(unknown, Files.readAllBytes(target)); }
    }

    @Test
    void freshModernPropertyIdentityRemainsTheOnlyReceipt(@TempDir Path directory) throws Exception {
        byte[] foreign = "unrelated auxiliary artifact\n".getBytes(StandardCharsets.US_ASCII);
        UUID identity;
        CapturingStore firstStore = new CapturingStore(directory, config(false));
        SailRepository first = open(firstStore);
        try { identity = firstStore.properties.savedStoreId(); assertNotNull(identity); }
        finally { first.shutDown(); }
        Files.write(directory.resolve(IDENTITY), foreign);
        CapturingStore secondStore = new CapturingStore(directory, config(false));
        SailRepository second = open(secondStore);
        try { assertEquals(identity, secondStore.properties.savedStoreId()); }
        finally { second.shutDown(); }
        assertArrayEquals(foreign, Files.readAllBytes(directory.resolve(IDENTITY)));
    }

    private static UUID readIdentity(Path directory) throws IOException {
        Path path = directory.resolve(IDENTITY);
        assertTrue(Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS));
        String encoded = Files.readString(path, StandardCharsets.US_ASCII);
        assertTrue(encoded.startsWith(HEADER));
        UUID identity = UUID.fromString(encoded.substring(HEADER.length()).strip());
        assertEquals(HEADER + identity + '\n', encoded);
        return identity;
    }
